// ─── File: src/test/java/com/bank/yield_demo/YieldTest.java ───
package com.bank.yield_demo;

import org.junit.jupiter.api.Test;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import static org.assertj.core.api.Assertions.*;

class YieldTest {

    // ═══ yield() is a hint — no guarantee ═══
    @Test
    void yield_isJustAHint() {
        AtomicInteger yieldCount = new AtomicInteger(0);

        Thread yielder = new Thread(() -> {
            for (int i = 0; i < 100; i++) {
                Thread.yield();  // hint — may be ignored!
                yieldCount.incrementAndGet();
            }
        });

        yielder.start();
        try { yielder.join(5000); } catch (InterruptedException e) { }

        assertThat(yieldCount.get()).isEqualTo(100);
        // Thread completed all 100 iterations — yield didn't block or delay!
        // yield() returns immediately, thread continues.
    }

    // ═══ yield() stays RUNNABLE — never WAITING ═══
    @Test
    void yield_staysRunnable() throws InterruptedException {
        CountDownLatch started = new CountDownLatch(1);
        AtomicBoolean running = new AtomicBoolean(true);

        Thread yielder = new Thread(() -> {
            started.countDown();
            while (running.get()) {
                Thread.yield();
            }
        });
        yielder.start();
        started.await();
        Thread.sleep(50);

        // Thread is RUNNABLE, not WAITING or TIMED_WAITING!
        assertThat(yielder.getState()).isEqualTo(Thread.State.RUNNABLE);
        running.set(false);
        yielder.join();
    }

    // ═══ BETTER: CountDownLatch instead of yield-spin ═══
    @Test
    void countDownLatch_betterThanYieldSpin() throws InterruptedException {
        CountDownLatch settled = new CountDownLatch(1);
        AtomicBoolean tradeProcessed = new AtomicBoolean(false);

        // Consumer: PROPERLY waits (no CPU waste!)
        Thread consumer = new Thread(() -> {
            try {
                settled.await();  // parks thread — ZERO CPU!
                tradeProcessed.set(true);
            } catch (InterruptedException e) { }
        });
        consumer.start();

        Thread.sleep(100);
        assertThat(consumer.getState()).isEqualTo(Thread.State.WAITING);  // parked!

        settled.countDown();  // signal!
        consumer.join(2000);

        assertThat(tradeProcessed.get()).isTrue();
    }

    // ═══ Java 9: onSpinWait() for spin loops ═══
    @Test
    void onSpinWait_betterThanYield() {
        AtomicBoolean ready = new AtomicBoolean(false);

        Thread spinner = new Thread(() -> {
            while (!ready.get()) {
                Thread.onSpinWait();  // Java 9: CPU-level PAUSE hint
                // More efficient than yield() — reduces power, helps hyperthreading
            }
        });

        spinner.start();
        try { Thread.sleep(50); } catch (InterruptedException e) { }
        ready.set(true);
        try { spinner.join(2000); } catch (InterruptedException e) { }

        assertThat(spinner.isAlive()).isFalse();
    }
}
